import SimpleParallax from "simple-parallax-js";
import parallaximg from "../body-pattern.jpg";
import { useTheme } from "./DarkMode";

const BodyParallax = () => {
    const { dark } = useTheme();
    return (
        <>
            {!dark && (
                <div className='bodyparallax absolute h-full w-full -z-10'>
                    <SimpleParallax delay={3} scale={1.5}>
                        <img src={parallaximg} alt="Parallax image" className="relative w-full h-full object-[75%] object-cover" />
                    </SimpleParallax>
                </div>
            )
            }
        </>
    )
}

export default BodyParallax;