import { useState, useEffect, useRef } from "react";
import { useSearchParams, useNavigate, Link } from "react-router-dom";

const VerifyOtp = () => {
  const [searchParams] = useSearchParams();
  const token = searchParams.get("token");
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [maskedEmail, setMaskedEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [secondsLeft, setSecondsLeft] = useState(null);
  const [resendCooldown, setResendCooldown] = useState(0);
  const timerRef = useRef(null);

  // fetch pending signup info (masked email + real expiry) on mount / refresh
  useEffect(() => {
    if (!token) {
      setError("Missing verification link.");
      setLoading(false);
      return;
    }

    fetch(`http://localhost:4000/user/signup/verify-info?token=${token}`)
      .then((res) => res.json())
      .then((result) => {
        if (result.status === "Success") {
          setMaskedEmail(result.email);
          startCountdown(new Date(result.expiresAt));
        } else {
          setError(result.message);
        }
      })
      .catch(() => setError("Something went wrong loading this page."))
      .finally(() => setLoading(false));

    return () => clearInterval(timerRef.current);
  }, [token]);

  const startCountdown = (expiresAt) => {
    clearInterval(timerRef.current);
    const tick = () => {
      const diff = Math.max(
        0,
        Math.floor((expiresAt.getTime() - Date.now()) / 1000),
      );
      setSecondsLeft(diff);
      if (diff === 0) clearInterval(timerRef.current);
    };
    tick();
    timerRef.current = setInterval(tick, 1000);
  };

  const formatTime = (s) => {
    const m = Math.floor(s / 60)
      .toString()
      .padStart(2, "0");
    const sec = (s % 60).toString().padStart(2, "0");
    return `${m}:${sec}`;
  };

  const onVerify = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setError("");
    try {
      const res = await fetch("http://localhost:4000/user/signup/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, otp }),
        credentials: "include",
      });
      const result = await res.json();
      if (result.status === "Success") {
        navigate("/user/login");
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.log(err);
      setError("Something went wrong. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  const onResend = async () => {
    if (resendCooldown > 0) return;
    setError("");
    try {
      const res = await fetch("http://localhost:4000/user/signup/resend-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token }),
        credentials: "include",
      });
      const result = await res.json();
      if (result.status === "Success") {
        startCountdown(new Date(result.expiresAt));
        setResendCooldown(30); // basic client-side throttle so they can't spam the button
        const cooldownInterval = setInterval(() => {
          setResendCooldown((prev) => {
            if (prev <= 1) {
              clearInterval(cooldownInterval);
              return 0;
            }
            return prev - 1;
          });
        }, 1000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      console.log(err);
    }
  };

  if (loading) {
    return (
      <main id="main">
        <p className="text-center py-16">Loading...</p>
      </main>
    );
  }

  const expired = secondsLeft === 0;

  return (
    <main id="main">
      <div className="signup-page-section">
        <h1 className="text-center text-3xl font-bold">
          <span>Verify</span> your email
        </h1>
        <div className="container">
          <div className="max-w-[480px] m-auto text-center">
            {maskedEmail && !expired && (
              <>
                <p className="mb-2">
                  Enter the 6-digit code sent to <strong>{maskedEmail}</strong>
                </p>
                <p className="mb-4 text-lg text-gray-500">
                  Code expires in{" "}
                  <span className="font-semibold text-black">
                    {formatTime(secondsLeft)}
                  </span>
                </p>

                <form onSubmit={onVerify}>
                  <input
                    className="w-full h-12 rounded-md border-2 p-2 text-center tracking-widest text-lg"
                    maxLength={6}
                    inputMode="numeric"
                    value={otp}
                    onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
                    placeholder="123456"
                    autoFocus
                  />
                  {error && (
                    <p className="text-red-500 text-sm mt-2">{error}</p>
                  )}
                  <div className="mb-4 text-center md:px-2 mt-4">
                    <div className="button">
                      <button
                        type="submit"
                        disabled={submitting || otp.length !== 6}
                        className="block w-full px-4 py-2 mb-3 bg-[#008b8b] text-black uppercase rounded-md text-sm disabled:cursor-not-allowed"
                      >
                        {submitting ? "Verifying..." : "Verify"}
                      </button>
                    </div>
                  </div>
                  <div className="mb-4 text-center md:px-2 mt-4">
                    <div className="button">
                      <button
                        type="button"
                        onClick={onResend}
                        disabled={resendCooldown > 0}
                        className="text-sm underline text-[#008b8b] disabled:text-gray-400 disabled:no-underline"
                      >
                        {resendCooldown > 0
                          ? `Resend code (${resendCooldown}s)`
                          : "Resend code"}
                      </button>
                    </div>
                  </div>
                </form>
              </>
            )}

            {(expired || (error && !maskedEmail)) && (
              <div>
                <p className="text-red-500 mb-4">
                  {expired ? "This code has expired." : error}
                </p>
                {expired && (
                  <button
                    onClick={onResend}
                    className="block w-full px-4 py-2 mb-3 bg-[#008b8b] text-black uppercase rounded-md text-sm"
                  >
                    Send a new code
                  </button>
                )}
              </div>
            )}

            <Link
              to="/user/signup"
              className="inline-block mt-6 text-sm text-[#008b8b]"
            >
              ← Back to signup
            </Link>
          </div>
        </div>
      </div>
    </main>
  );
};

export default VerifyOtp;
