// Scroll To Top button
const ScrollToTopButton = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [isHover, setHover] = useState(false);

  // Show or hide the button based on scroll position
  const toggleVisibility = () => {
    if (window.scrollY > window.innerHeight / 1.99) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  };

  // Scroll to the top of the page
  const scrollToTop = (e) => {
    e.target.blur();
    window.scrollTo({
      top: 0,
      behavior: "smooth", // Smooth scroll behavior
    });
  };

  // Event listener for scroll
  useEffect(() => {
    window.addEventListener("scroll", toggleVisibility);

    // Cleanup event listener on unmount
    return () => {
      window.removeEventListener("scroll", toggleVisibility);
    };
  }, []);

  // React-Spring animation for fading the button
  const buttonAnimation = useSpring({
    //display: isVisible ? 'block' : 'none',
    transform: isVisible ? "translateX(0%)" : "translateX(120%)", // Add slight slide effect
    backgroundImage: isHover
      ? "linear-gradient(-90deg, rgb(2, 132, 199), rgb(14, 165, 233))"
      : "linear-gradient(90deg, rgb(37, 99, 235), rgb(59, 130, 246))",
    config: { tension: 300, friction: 30 },
  });

  return (
    <animated.button
      className={
        "scrollToTop fixed bottom-20 right-0 w-10 h-10 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] uppercase font-bold border-0 shadow-lg pointer rounded-l-full text-sm z-20"
      }
      aria-label={"Scroll to top button"}
      onClick={scrollToTop}
      style={{
        ...buttonAnimation,
        transition: elastic,
      }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      <FontAwesomeIcon icon={faArrowUp}></FontAwesomeIcon>
    </animated.button>
  );
};

const SESSION_KEY = "welcomeModalClosed";

// APP //
function App() {
  const [isModalOpen, setModalOpen] = useState(true);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 100) {
        // Add class if scrolled past 100px
        document.body.classList.add("scrolled");
      } else {
        // Remove class if less than 100px
        document.body.classList.remove("scrolled");
      }
    };

    // Add scroll event listener
    window.addEventListener("scroll", handleScroll);

    // Cleanup the event listener on unmount
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const closemodal = () => {
    sessionStorage.setItem(SESSION_KEY, "true");
    setModalOpen(false);
    document.documentElement.removeAttribute("modal");
  };

  return (
    <AuthProvider>
      <ThemeProvider>
        <BodyParallax />
        <ScrollToTop />
        <Header />
        <PageWrapper />
        <ScrollToTopButton />
        <Routes>
          <Route
            path="/user/login"
            element={
              <BasicRoute>
                <Login />
              </BasicRoute>
            }
          />
          <Route
            path="/user/signup"
            element={
              <BasicRoute>
                <Signup />
              </BasicRoute>
            }
          />
          <Route
            path="/user/verify"
            element={
              <BasicRoute>
                {" "}
                <VerifyOtp />
              </BasicRoute>
            }
          />
          <Route path="/contact-us" element={<ContactForm />} />
          {/* Menu Route */}
          <Route
            exact
            path="/"
            element={
              <AuthRoute>
                <Home />
              </AuthRoute>
            }
          />
          <Route
            path="/about"
            element={
              <AuthRoute>
                <About />
              </AuthRoute>
            }
          />
          <Route
            path="/gallery"
            element={
              <AuthRoute>
                <Gallery />
              </AuthRoute>
            }
          />
          <Route
            path="/testimonials"
            element={
              <AuthRoute>
                <Testimonials />
              </AuthRoute>
            }
          />
          <Route
            path="/my-account"
            element={
              <AuthRoute>
                <MyAccount />
              </AuthRoute>
            }
          />
          <Route path="*" element={<PageNotFound />} />
        </Routes>
        <footer id="footer">
          <Footer />
        </footer>
        <Modal show={isModalOpen} onClose={closemodal} />
      </ThemeProvider>
    </AuthProvider>
  );
}

const PageWrapper = () => {
  usePageClass();
  return null;
};

export default App;
// END APP //
