import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { useForm, Controller } from "react-hook-form";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCalendar, faChevronDown } from "@fortawesome/free-solid-svg-icons";
import { useState } from "react";
import logo from "../logo.webp";

export const Form = () => {
    const {register, handleSubmit, reset, control, formState: {errors}} = useForm();
    const [loading, setLoading] = useState(false);
    const onSubmit = async (data) => {
        setLoading(true);
        try {
            // This is where you would send data to a server or API
            const res = await fetch("https://server-t9ab.onrender.com/submit", {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify(data),
            });
            const result = await res.text();
            alert(result);
            reset();
        } catch (err) {
            alert('Failed to submit details at this time. Please try again later.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container">
            <div className="m-4">
                {loading ? (
                    <div className="flex justify-center py-16">
                        <span className="relative flex items-center justify-center size-24">
                            <span className="absolute inline-flex h-full w-full animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-[#61dafb]"></span>
                            <span className="relative inline-flex items-center justify-center size-24 animate-pulse rounded-full bg-[#61dafb] text-xs text-slate-500">
                                <span className="absolute inline-flex h-1/2 w-1/2 animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-slate-500"></span>
                            Please wait...</span>
                        </span>
                    </div>
                ) :
                (<form onSubmit={handleSubmit(onSubmit)} className="md:flex md:flex-wrap md:justify-center" autoComplete="off">
                    <div className="mb-4 overflow-hidden md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="firstname">First Name</label></div>
                        <div className="relative form-field">
                            <input
                            id="firstname"
                            className="w-full h-12 rounded-md border-2 p-2 shadow-inner appearance-none"
                            type="text"
                            autoComplete="on"
                            placeholder="Enter your first name"
                            {...register("firstname", {required: "First name is required",
                                pattern:{value: /^[A-Za-z]+$/i,
                                message: "Only alphabets are allowed",}})}
                            />
                            {errors.firstname && <small style={{ color: "red" }}>{errors.firstname.message}</small>}
                        </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="lastname">Last Name</label></div>
                        <div className="relative form-field">
                            <input
                            id="lastname"
                            className="w-full h-12 rounded-md border-2 p-2 shadow-inner appearance-none"
                            type="text"
                            autoComplete="on"
                            placeholder="Enter your last name"
                            {...register("lastname",
                                {pattern:{value: /^[A-Za-z]+$/i,
                                message: "Only alphabets are allowed",}})}
                            />
                            {errors.lastname && <small style={{color: "red"}}>{errors.lastname.message}</small>}
                        </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="email">Email</label></div>
                        <div className="relative form-field">
                            <input
                            id="email"
                            className="w-full h-12 rounded-md border-2 p-2 shadow-inner appearance-none"
                            autoComplete="on"
                            placeholder="Enter a valid email address"
                            type="email"
                            {...register("email",
                                {required: "Email address is required",
                                pattern:{value: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/,
                                message: "Enter a valid email address",}})}
                            />
                            {errors.email && <small style={{ color: "red" }}>{errors.email.message}</small>}
                        </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="tel">Phone</label></div>
                        <div className="relative form-field">
                            <input
                            id="tel"
                            className="w-full h-12 rounded-md border-2 p-2 shadow-inner appearance-none"
                            autoComplete="on"
                            placeholder="Enter your phone number"
                            type="tel"
                            inputMode="numeric"
                            maxLength={10}
                            {...register("phone",
                                {required: "Phone number is required",
                                pattern:{value:/^[0-9]{10}$/,
                                message: "Phone number must be 10 digits only"}})}
                            />
                            {errors.phone && <small style={{ color: "red" }}>{errors.phone.message}</small>}
                        </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="gender">Gender</label></div>
                        <div className="relative form-field">
                            <select
                            id="gender"
                            className="w-full h-12 rounded-md border-2 p-2 shadow-inner appearance-none cursor-pointer"
                            {...register("gender",
                                {required: "Gender is required",
                                message: "Please select an option"})}
                                defaultValue="">
                                <option value="" disabled hidden>Select your gender</option>
                                <option value="male">Male</option>
                                <option value="female">Female</option>
                            </select>
                            <FontAwesomeIcon icon={faChevronDown} color="#272b36" size="xl" className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 pointer-events-none"/>
                        </div>
                        {errors.gender && <small style={{ color: "red" }}>{errors.gender.message}</small>}
                    </div>
                    <div className="mb-4 md:w-1/2 md:float-left md:px-2">
                        <div className="label"><label htmlFor="dob">Date of Birth</label></div>
                        <div className="relative form-field">
                            <Controller
                                name="dob"
                                control={control}
                                defaultValue={null}
                                rules={{required: "Date of birth is required", message: "Please select date of birth"}}
                                render={({field}) => (
                                    <DatePicker
                                        className="w-full h-12 rounded-md border-2 !p-2 shadow-inner appearance-none cursor-pointer" id="dob"
                                        wrapperClassName="w-full"
                                        showIcon
                                        icon={<FontAwesomeIcon icon={faCalendar} color="#272b36" size="xl" className="right-2 top-1/2 transform -translate-y-1/2 cursor-pointer"/>}
                                        toggleCalendarOnIconClick
                                        placeholderText="Select your date of Birth"
                                        selected={field.value}
                                        onChange={(date) => field.onChange(date)}
                                        dateFormat="yyyy-MM-dd"
                                        maxDate={new Date()}
                                        showTimeSelect={false}
                                        showMonthDropdown
                                        showYearDropdown
                                        scrollableYearDropdown
                                        yearDropdownItemNumber={18}
                                        dropdownMode="scroll"
                                    />
                                )}
                            />{errors.dob && <small style={{ color: "red" }}>{errors.dob.message}</small>}
                        </div>
                    </div>
                    <div className="w-full mb-4 overflow-hidden md:px-2">
                        <div className="label"><label htmlFor="comments">Comments</label></div>
                        <div className="relative form-field">
                            <textarea
                            id="comments"
                            className="w-full rounded-md border-2 p-2 shadow-inner appearance-none"
                            placeholder="Add additional comments/feedback"
                            {...register("comments")}
                            />
                        </div>
                    </div>
                    <div className="mb-4 text-center md:px-2">
                        <div className="button"><button className="block px-4 py-2 mb-2 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] capitalize shadow-lg pointer rounded-md text-sm" type="submit" disabled={loading}>{loading ? 'Submitting' : 'Submit'}</button></div>
                    </div>
                </form>)
                }
            </div>
        </div>
    );
}

const ContactForm = () => {
    return (
        <>
        <title>Contact Us</title>
        <meta name="description" content="Contact Us"/>
        <meta property="og:title" content="Contact Us | My New React App" />
        <meta property="og:image" content={logo} />
        <main id="main">
            <div className="contact-page-section">
                <h1 className="text-center text-3xl font-bold capitalize"><span>Contact </span>Us</h1>
                <Form/>
            </div>
        </main>
        </>
    );
}
export default ContactForm;