import { useState } from "react";
import { useForm } from "react-hook-form";
import { useAuth } from "./auth/auth";
import { useLocation, useNavigate } from "react-router-dom";
import logo from '../../logo.webp';
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEye, faEyeSlash } from "@fortawesome/free-solid-svg-icons";

const Login = () => {
    const { register, handleSubmit, reset, setError, formState: { errors } } = useForm();
    const [loading, setLoading] = useState(false);
    const [user, setUser] = useState('');
    const [seePassword, setSeePassword] = useState(false);
    const auth = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const changePath = () => { navigate("/user/signup") };

    const onLogin = async (data) => {
        setLoading(true);
        try {
            const res = await fetch("https://user-server-nzts.onrender.com/user/login", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(data),
                credentials: "include"
            });
            const result = await res.json();
            if (result.status === "Failed" && result.message) {
                setError("form", {
                    type: "server",
                    message: result.message
                });
            } else if (result.status === "Success" && result.data) {
                const from = location.state?.from;
                const user = result.data
                auth.login(user);
                reset();
                if (from && from !== "/user/login" && from !== "/user/signup") {
                    navigate(from, { replace: true });
                } else {
                    navigate("/", { replace: true });
                }
            }
        } catch (err) {
            console.log(err);
        } finally {
            setLoading(false);
        }
    };
    return (
        <>
            <title>Login</title>
            <meta name="description" content="Login" />
            <meta property="og:title" content="Login | My New React App" />
            <meta property="og:image" content={logo} />
            <main id="main">
                <div className="login-page-section">
                    <h1 className="text-center text-3xl font-bold"><span>Log</span>in</h1>
                    <div className="container">
                        <div className="max-w-[480px] m-auto">
                            <div className="loginform">
                                <div className="mb-4 text-center md:px-2">
                                    <div className="button"><button onClick={changePath} className="block font-semibold text-[#008b8b] hue-rotate-[45deg] text-lg underline pointer" disabled={loading}>Don't have an account? Sign up here</button></div>
                                </div>
                                {loading ?
                                    (<div className="flex justify-center py-16">
                                        <span className="relative flex items-center justify-center size-24">
                                            <span className="absolute inline-flex h-full w-full animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-[#61dafb]"></span>
                                            <span className="relative inline-flex items-center justify-center size-24 animate-pulse rounded-full bg-[#61dafb] text-xs text-slate-500">
                                                <span className="absolute inline-flex h-1/2 w-1/2 animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-slate-500"></span>
                                                Please wait...</span>
                                        </span>
                                    </div>)
                                    :
                                    (<form onSubmit={handleSubmit(onLogin)} onChange={(e) => setUser(e.target.value)} autoComplete="off">
                                        {errors.form && <div className="text-center" {...register("form")}><small style={{ color: "red" }}>{errors.form.message}</small></div>}
                                        <div className="mb-4 overflow-hidden md:px-2">
                                            <div className="label"><label htmlFor="email">Email</label></div>
                                            <div className="relative form-field">
                                                <input
                                                    id="email"
                                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                                    autoComplete="on"
                                                    placeholder="Enter a valid email address"
                                                    type="email"
                                                    {...register("email",
                                                        {
                                                            required: "Email address is required",
                                                            pattern: {
                                                                value: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/,
                                                                message: "Enter a valid email address",
                                                            }
                                                        })}
                                                />
                                                {errors.email && <small style={{ color: "red" }}>{errors.email.message}</small>}
                                            </div>
                                        </div>
                                        <div className="mb-4 overflow-hidden md:px-2">
                                            <div className="label"><label htmlFor="password">Password</label></div>
                                            <div className="relative form-field">
                                                <input
                                                    id="password"
                                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                                    type={seePassword ? "text" : "password"}
                                                    autoComplete="on"
                                                    placeholder="Enter your password"
                                                    minLength={8}
                                                    maxLength={28}
                                                    {...register("password", { required: "Password is required", })}
                                                />
                                                <FontAwesomeIcon onClick={() => setSeePassword(prev => !prev)} icon={seePassword ? faEye : faEyeSlash} color="#272b36" size="xl" className="absolute right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" />
                                                {errors.password && <small style={{ color: "red" }}>{errors.password.message}</small>}
                                            </div>
                                        </div>
                                        <div className="mb-4 text-center md:px-2">
                                            <div className="button"><button className="block px-4 py-2 mb-2 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-md text-sm" type="submit" disabled={loading}>{loading ? 'Loggin in' : 'Login'}</button></div>
                                        </div>
                                    </form>)
                                }
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        </>
    );
};
export default Login;