import { Link } from "react-router-dom";
import logo from "../../logo.webp";
import { useAuth } from "./auth/auth";
import { useEffect, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPenToSquare } from "@fortawesome/free-solid-svg-icons";
import { AccountChanges } from "./AccountChanges";

const MyAccount = () => {
  const { user, loading } = useAuth();
  const [openModal, setOpenModal] = useState(false);

  useEffect(() => {
    if (openModal) {
      document.documentElement.classList.add("modal-open");
    } else {
      document.documentElement.classList.remove("modal-open");
    }
  }, [openModal]);

  const tabs = [
    {
      title: "Personal Information",
      editable: true,
      data: [
        {
          id: user._id,
          label: "First name",
          value: user.firstname,
        },
        {
          id: user._id,
          label: "Last name",
          value: user.lastname,
        },
        {
          id: user._id,
          label: "Email",
          value: (
            <Link
              className="text-[#008b8b] hue-rotate-[45deg] underline hover:text-slate-500"
              to={"mailto:" + user.email}
            >
              {user.email}
            </Link>
          ),
        },
        {
          id: user._id,
          label: "Phone",
          value: (
            <Link
              className="text-[#008b8b] hue-rotate-[45deg] underline hover:text-slate-500"
              to={"tel:" + user.phone}
            >
              {user.phone}
            </Link>
          ),
        },
        {
          id: user._id,
          label: "Gender",
          value: user.gender,
        },
        {
          id: user._id,
          label: "Date of birth",
          value: new Date(user.dob).toLocaleDateString("en-US", {
            year: "numeric",
            month: "long",
            day: "numeric",
          }),
        },
      ],
    },
    {
      title: "Private Information",
      data: [
        {
          id: user._id,
          label: "User id",
          value: user._id,
        },
        {
          id: user._id,
          label: "Account created since",
          value: user.created,
        },
        {
          id: user._id,
          label: "Online status",
          value: user.lastOnline,
        },
      ],
    },
  ];

  const [activeTab, setActiveTab] = useState("Personal Information");

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <>
      <title>{`${user.firstname}` + "'s Account"}</title>
      <meta name="description" content={`${user.firstname}` + "'s Account"} />
      <meta
        property="og:title"
        content={`${user.firstname}` + "'s Account" + " | My New React App"}
      />
      <meta property="og:image" content={logo} />
      <main id="main">
        <div className="myaccount-page-section">
          <h1 className="text-center text-3xl font-bold uppercase">
            <span>Welcome,</span> {`${user.firstname} ${user.lastname}`}
          </h1>
          <div className="container">
            <div className="m-4">
              <ul className="account overflow-hidden border-2 rounded-xl shadow-lg">
                <li className="account-tabs overflow-x-auto bg-[#e0eefe] rounded-t-lg">
                  <ul className="inline-flex">
                    {tabs.map(({ title }) => (
                      <li
                        key={title}
                        onClick={() => setActiveTab(title)}
                        className={
                          "px-4 bg-gradient-to-r from-blue-600 to-blue-500 border-r-2 cursor-pointer select-none" +
                          (activeTab === title ? " bg-gradient-to-l" : "")
                        }
                      >
                        <h2
                          className={
                            "text-xs md:text-sm lg:text-lg" +
                            (activeTab === title
                              ? " text-[#e0eefe] font-bold opacity-100 underline"
                              : " text-[#e0eefe] opacity-75")
                          }
                        >
                          {title}
                        </h2>
                      </li>
                    ))}
                  </ul>
                </li>
                {tabs
                  .filter((tab) => tab.title === activeTab)
                  .map(({ title, data, editable }, index) => (
                    <li
                      key={`${title}-${index}`}
                      className={
                        title + " p-4 bg-gradient-to-bl from-sky-200 to-sky-50"
                      }
                    >
                      <ul key={title}>
                        {editable && (
                          <div
                            key={`${index}-${editable}`}
                            onClick={() => setOpenModal(true)}
                            className="cursor-pointer float-right mx-2"
                          >
                            <FontAwesomeIcon
                              icon={faPenToSquare}
                              className="text-slate-700"
                            />
                          </div>
                        )}
                        <AccountChanges
                          show={openModal}
                          onClose={() => setOpenModal(false)}
                        />
                        {data.map(({ label, value, id }, index) => (
                          <li
                            key={`${id}-${index}`}
                            className="text-xs md:text-sm"
                          >
                            <p className="inline-block font-bold text-slate-900">
                              <b className="text-slate-700">{label}: </b>
                              {value}
                            </p>
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
              </ul>
            </div>
          </div>
        </div>
      </main>
    </>
  );
};
export default MyAccount;
