import logo from "/newreactsite/src/logo.svg";
import { Link, useLocation } from "react-router-dom";
import { useSpring, animated } from "@react-spring/web";
import { Form } from "./Forms";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faFacebook,
  faXTwitter,
  faInstagram,
} from "@fortawesome/free-brands-svg-icons";
import {
  faAddressCard,
  faCircleUser,
  faEnvelope,
  faHouse,
  faImage,
  faMapLocationDot,
  faPhone,
  faShareNodes,
  faStar,
} from "@fortawesome/free-solid-svg-icons";
import { useAuth } from "./user/auth/auth";
import backgroundPattern from "../components/images/banner-pattern.png";

function Footer() {
  const auth = useAuth();
  const rotateInf = useSpring({
    from: { rotate: 0 },
    to: { rotate: 360 },
    loop: true,
    config: { duration: 20000 },
  });
  const location = useLocation();
  const isVisible = location.pathname !== "/contact-us";
  const pathnames = location.pathname;
  return (
    <>
      {!auth.user ? null : (
        <>
          {isVisible ? (
            <section className="contact-form-section mb-10">
              <h2 className="text-center text-2xl font-bold capitalize">
                <span>Contact </span>Us
              </h2>
              <Form />
            </section>
          ) : null}
          <section
            className="footer max-md:!bg-gradient-to-br max-md:from-sky-200 max-md:to-sky-50 md:pt-20 md:pb-4"
            style={{
              backgroundImage: `url(${backgroundPattern})`,
              backgroundAttachment: "fixed",
              backgroundPosition: "bottom",
            }}
          >
            <div className="container">
              <div className="flex flex-wrap overflow-hidden md:p-2 md:bg-[#e0eefe] md:from-sky-200 md:to-sky-50 md:rounded-xl md:shadow-lg lg:p-4">
                <div className="useful-lnks inline-flex flex-col flex-[1_0_50%] text-[#272b36] md:flex-[1_0_25%] lg:basis-auto">
                  <h2 className="text-xl text-[#272b36] font-bold">
                    Useful Links:
                  </h2>
                  <ul className="text-sm lg:text-base">
                    <li className="group mb-1 select-none">
                      <Link
                        to="/"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faHouse}
                          size="lg"
                          className="mr-2"
                        />
                        Home
                      </Link>
                    </li>
                    <li className="group mb-1 select-none">
                      <Link
                        to="/about"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/about"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faAddressCard}
                          size="lg"
                          className="mr-2"
                        />
                        About
                      </Link>
                    </li>
                    <li className="group mb-1 select-none">
                      <Link
                        to="/gallery"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/gallery"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faImage}
                          size="lg"
                          className="mr-2"
                        />
                        Gallery
                      </Link>
                    </li>
                    <li className="group mb-1 select-none">
                      <Link
                        to="/testimonials"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/testimonials"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faStar}
                          size="lg"
                          className="mr-2"
                        />
                        Testimonials
                      </Link>
                    </li>
                    <li className="group mb-1 select-none">
                      <Link
                        to="/contact-us"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/contact-us"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faPhone}
                          size="lg"
                          className="mr-2"
                        />
                        Contact Us
                      </Link>
                    </li>
                    <li className="group mb-1 select-none rounded-lg">
                      <Link
                        to="/my-account"
                        className={
                          "relative overflow-hidden inline-block p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10" +
                          (pathnames === "/my-account"
                            ? " bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] pointer-events-none font-bold"
                            : "")
                        }
                      >
                        <FontAwesomeIcon
                          icon={faCircleUser}
                          size="lg"
                          className="mr-2"
                        />
                        My Account
                      </Link>
                    </li>
                  </ul>
                </div>
                <div className="comms inline-flex flex-col flex-[1_0_50%] text-[#272b36] md:flex-[1_0_25%] lg:basis-auto">
                  <h2 className="text-xl text-[#272b36] font-bold">
                    Communications:
                  </h2>
                  <ul className="text-sm lg:text-base">
                    <li className="select-none">
                      <Link
                        to={"mailto:test@test.com"}
                        className="group relative overflow-hidden inline-flex items-center p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10"
                      >
                        <span className="relative overflow-hidden p-2 mr-2 rounded-lg before:bg-gradient-to-tl before:from-sky-600 before:to-sky-500 group-hover:before:opacity-0">
                          <FontAwesomeIcon
                            icon={faEnvelope}
                            size="xl"
                            color="#e0eefe"
                          />
                        </span>
                        test@test.com
                      </Link>
                    </li>
                    <li className="select-none">
                      <Link
                        to={"tel:0123456789"}
                        className="group relative overflow-hidden inline-flex items-center p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10"
                      >
                        <span className="relative overflow-hidden p-2 mr-2 rounded-lg before:bg-gradient-to-tl before:from-sky-600 before:to-sky-500 group-hover:before:opacity-0">
                          <FontAwesomeIcon
                            icon={faPhone}
                            size="xl"
                            color="#e0eefe"
                          />
                        </span>
                        012 345 6789
                      </Link>
                    </li>
                    <li className="select-none">
                      <Link
                        to={""}
                        className="group relative overflow-hidden inline-flex items-center p-2 font-semi-bold rounded-lg before:opacity-0 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe] z-10"
                      >
                        <span className="relative flex-[1_0_auto] overflow-hidden p-2 mr-2 rounded-lg before:bg-gradient-to-tl before:from-sky-600 before:to-sky-500 group-hover:before:opacity-0">
                          <FontAwesomeIcon
                            icon={faMapLocationDot}
                            size="xl"
                            color="#e0eefe"
                          />
                        </span>
                        0123 Test Building, Test Area
                        <br />
                        Test City, Test State 012345
                      </Link>
                    </li>
                  </ul>
                </div>
                <div className="loc relative inline-flex flex-col flex-[1_0_50%] justify-center text-[#272b36]">
                  <iframe
                    title="Google Maps iFrame"
                    src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5250.127653224991!2d2.2944809999999936!3d48.85837!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x47e66e2964e34e2d%3A0x8ddca9ee380ef7e0!2sEiffel%20Tower!5e0!3m2!1sen!2sus!4v1752179628401!5m2!1sen!2sus"
                    className="w-full h-full rounded-lg shadow-md"
                  ></iframe>
                </div>
              </div>
              <div id="logo" className="w-16 m-auto pt-4">
                <animated.img
                  /* style={{ ...rotateInf }} */ src={logo}
                  className="App-logo"
                  alt="logo"
                ></animated.img>
              </div>
              <div className="social max-w-[280px] flex justify-evenly py-4 m-auto">
                <span className="flex gap-1 font-bold text-[#272b36]">
                  Follow us{" "}
                  <FontAwesomeIcon
                    icon={faShareNodes}
                    size="xl"
                    color="#272b36"
                  />
                </span>
                <span className="mr-2 border-r-2 border-[#272b36] opacity-30"></span>
                <ul className="flex justify-center gap-2 text-center">
                  <li>
                    <Link
                      to={"/"}
                      className="group relative overflow-hidden p-2 text-[#e0eefe] duration-300 z-10 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 before:rounded-lg hover:before:brightness-[1.5] hover:text-[#272b36]"
                      rel="nofollow noopener noreferrer"
                      aria-label="Facebook page"
                    >
                      <FontAwesomeIcon icon={faFacebook} size="xl" />
                    </Link>
                  </li>
                  <li>
                    <Link
                      to={"/"}
                      className="group relative overflow-hidden p-2 text-[#e0eefe] duration-300 z-10 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 before:rounded-lg hover:before:brightness-[1.5] hover:text-[#272b36]"
                      rel="nofollow noopener noreferrer"
                      aria-label="Twitter page"
                    >
                      <FontAwesomeIcon icon={faXTwitter} size="xl" />
                    </Link>
                  </li>
                  <li>
                    <Link
                      to={"/"}
                      className="group relative overflow-hidden p-2 text-[#e0eefe] duration-300 z-10 before:bg-gradient-to-r before:from-blue-600 before:to-blue-500 before:rounded-lg hover:before:brightness-[1.5] hover:text-[#272b36]"
                      rel="nofollow noopener noreferrer"
                      aria-label="Instagram page"
                    >
                      <FontAwesomeIcon icon={faInstagram} size="xl" />
                    </Link>
                  </li>
                </ul>
              </div>
            </div>
          </section>
          <section className="footercopy bg-white">
            <div className="container">
              <p className="text-center text-slate-800 p-1">
                New React Site © 2025
              </p>
            </div>
          </section>
        </>
      )}
    </>
  );
}

export default Footer;
