import banner1 from '../components/images/pexels-godiatima-4955393.webp';
import banner2 from '../components/images/pexels-ron-lach-10638069.webp';
import banner3 from '../components/images/pexels-sejio402-6477212.webp';
import bannerPattern from '../components/images/banner-pattern.png';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import '../Carousel.css';
import { AboutContent } from './About';
import { GalleryContent } from './Gallery';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCircleDot } from '@fortawesome/free-solid-svg-icons';
import { TestimonialsSlider } from './Testimonials';
import logo from "../logo.webp";
import { Link } from 'react-router-dom';

const carouselcontent = [
    {
        id: 1,
        img: banner1,
        alt: "Banner 1",
        caption: <div className='text-center md:text-left'><h2 className='text-2xl text-[#f0f3f5] font-bold mb-4 capitalize md:text-4xl'><span className='text-[#f0f3f5] invert-[100]'>Welcome to</span> caption<br />for banner 1</h2><p className='text-sm font-semibold text-[#f0f3f5] md:text-[#272b36] md:text-xl'>Lorem Ipsum is simply dummy text of the printing and typesetting industry.</p></div>,
        cTA: <button><Link className="block px-6 py-3 mb-1 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] capitalize shadow-lg pointer rounded-md text-sm" to="/about">Learn More</Link></button>

    },
    {
        id: 2,
        img: banner2,
        alt: "Banner 2",
        caption: <div className='text-center md:text-left'><h2 className='text-2xl text-[#f0f3f5] font-bold mb-4 capitalize md:text-4xl'><span className='text-[#f0f3f5] invert-[100]'>Welcome to</span> caption<br />for banner 2</h2><p className='text-sm font-semibold text-[#f0f3f5] md:text-[#272b36] md:text-xl'>Lorem Ipsum is simply dummy text of the printing and typesetting industry.</p></div>,
        cTA: <button><Link className="block px-6 py-3 mb-1 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] capitalize shadow-lg pointer rounded-md text-sm" to="/about">Learn More</Link></button>

    },
    {
        id: 3,
        img: banner3,
        alt: "Banner 3",
        caption: <div className='text-center md:text-left'><h2 className='text-2xl text-[#f0f3f5] font-bold mb-4 capitalize md:text-4xl'><span className='text-[#f0f3f5] invert-[100]'>Welcome to</span> caption<br />for banner 3</h2><p className='text-sm font-semibold text-[#f0f3f5] md:text-[#272b36] md:text-xl'>Lorem Ipsum is simply dummy text of the printing and typesetting industry.</p></div>,
        cTA: <button><Link className="block px-6 py-3 mb-1 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] capitalize shadow-lg pointer rounded-md text-sm" to="/about">Learn More</Link></button>

    }
];

export const Carousel = () => {
    const isMoble = window.innerWidth < 768;

    const settings = {
        //fade: true,
        cssEase: 'ease-in-out',
        dots: true,
        customPaging: i => (<FontAwesomeIcon icon={faCircleDot} color='lightgrey' size='xs' className='pb-4 [.slick-active_&]:text-lg duration-300' />),
        infinite: true,
        speed: 300,
        slidesToShow: 1,
        slidesToScroll: 1,
        arrows: true,
        autoplay: true,
        pauseOnFocus: true,
        lazyLoad: 'ondemand',
        autoplaySpeed: 6000,
        responsive: [
            {
                breakpoint: 768,
                settings: {
                    arrows: false
                }
            }
        ]
    };

    return (
        <section className="carousel-wrapper relative overflow-hidden w-full h-[60vh] sm:h-[calc(100vh-6rem)] lg:h-[100vh]">
            <Slider className='homeBanner' {...settings}>
                {carouselcontent.map(({ id, img, alt, caption, cTA }) => (
                    <div key={id}>
                        <img
                            src={img}
                            alt={alt}
                            className='w-full h-[60vh] object-cover object-[80%] sm:object-[right] sm:h-[calc(100vh-6rem)] md:object-[50%] lg:h-[100vh] lg:object-top' loading="lazy" />
                        <div className='caption absolute text-[#f9f9f9] top-0 w-full h-full'>
                            <div className='captiontext relative mx-[1%] bg-[rgb(224_238_254_/_70%)] top-[65%] -translate-y-1/2 p-4 rounded-xl sm:top-3/4 md:w-1/2 md:left-16 md:top-1/2 md:max-w-1/2 md:mx-0'>
                                {caption}
                                {isMoble ? null : cTA}
                            </div>
                        </div>
                    </div>
                ))}
            </Slider>
        </section>
    );
};

const Home = () => {
    return (
        <>
            <title>Home</title>
            <meta name="description" content="Home" />
            <meta property="og:title" content="Home | My New React App" />
            <meta property="og:image" content={logo} />
            <main id='main'>
                <Carousel />
                <section className='about-section mb-10'>
                    <AboutContent />
                </section>
                <section className='testimonials-section mb-10'>
                    <h2 className="text-center text-2xl font-bold capitalize"><span>Case</span> Studies</h2>
                    <TestimonialsSlider />
                </section>
                <section className='gallery-section mb-10 py-20 shadow-lg' style={
                    {
                        backgroundImage: `url(${bannerPattern})`,
                        backgroundSize: 'cover',
                        backgroundPosition: 'bottom',
                        backgroundAttachment: 'fixed'
                    }
                }>
                    <h2 className="text-center text-2xl font-bold capitalize"><span>Check Our </span>ins and outs</h2>
                    <GalleryContent />
                </section>
            </main>
        </>
    );
}

export default Home;