const AnimatedIcon = ({ title, icon, content /* entryIndexRef */ }) => {
  const [ref, inView] = useInView({
    once: true,
    rootMargin: "-30% 0px",
  });

  /* const localIndex = useRef(null); */

  const styles /* api */ = useSpring({
    opacity: inView ? 1 : 0,
    y: inView ? 0 : 100,
    config: {
      tension: 300,
      friction: 60,
    },
  });

  /* useEffect(() => {
        if (inView && localIndex.current === null) {
            localIndex.current = entryIndexRef.current++;
        }

        if (inView) {
            api.start({
                opacity: 1,
                y: 0,
                delay: localIndex.current * 120,
                config: {
                    tension: 300,
                    friction: 30
                }
            });
        } else {
            api.start({
                reverse: true
            })
        }
    }, [inView, api, entryIndexRef]); */

  return (
    <animated.div
      className="icon-content flex flex-col flex-[49%] gap-4 p-3 bg-[#e0eefe] text-center rounded-xl shadow-md lg:flex-[24%]"
      ref={ref}
      style={{
        ...styles,
        /* opacity: styles.opacity,
                transform: styles.y.to(y => `translateY(${y}px)`) */
      }}
    >
      {title}
      {icon}
      {content}
    </animated.div>
  );
};

// About content
export const AboutContent = () => {
  /* const entryIndexRef = useRef(0); */
  const location = useLocation();

  /* useEffect(() => {
        entryIndexRef.current = 0;
    }, [location.pathname]); */

  const [ref, inView] = useInView(
    () => ({
      from: {
        opacity: 0,
        x: -100,
      },
      to: {
        opacity: 1,
        x: 0,
      },
      config: {
        tension: 300,
        friction: 60,
      },
    }),
    {
      once: true,
      rootMargin: "-50% 0%",
    },
  );

  const [ref2, inView2] = useInView(
    () => ({
      from: {
        opacity: 0,
        x: 100,
      },
      to: {
        opacity: 1,
        x: 0,
      },
      config: {
        tension: 300,
        friction: 60,
      },
    }),
    {
      once: true,
      rootMargin: "-50% 0%",
    },
  );

  //Modal
  const [isModalOpen, setModalOpen] = useState(false);

  const openModal = () => setModalOpen(true);
  const closeModal = () => setModalOpen(false);

  useEffect(() => {
    if (isModalOpen) {
      document.documentElement.classList.add("modal-open");
    } else {
      document.documentElement.classList.remove("modal-open");
    }

    return () => document.documentElement.classList.remove("modal-open");
  }, [isModalOpen]);

  //Modal CTA
  const [isModalCtaOpen, setModalCtaOpen] = useState(false);

  const openModalCta = () => setModalCtaOpen(true);
  const closeModalCta = () => setModalCtaOpen(false);

  useEffect(() => {
    if (isModalCtaOpen) {
      document.documentElement.classList.add("modal-open");
    } else {
      document.documentElement.classList.remove("modal-open");
    }

    // Clean up by removing the class when the component unmounts or `isModalOpen` changes
    return () => document.documentElement.classList.remove("modal-open");
  }, [isModalCtaOpen]);

  const isPage = location.pathname === "/about";

  const ViewMore = () => {
    return (
      <>
        {!isPage && (
          <div className="button w-full text-center py-4 !mr-0 md:w-auto md:pt-0">
            <button>
              <Link
                className="block px-4 py-2 mb-1 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] shadow-lg pointer rounded-md text-sm"
                to="/about"
              >
                View More
              </Link>
            </button>
          </div>
        )}
      </>
    );
  };
  return (
    <>
      <div className="container">
        <div className="sm:m-4">
          <h1 className="text-center text-3xl font-bold">
            <span>What is</span> Lorem Ipsum?
          </h1>
          <div className="aboutintro flex flex-wrap gap-8 overflow-hidden mb-4 bg-gradient-to-tl from-sky-200 to-sky-50 rounded-xl shadow-lg md:flex-nowrap lg:items-center">
            <animated.div
              className="aboutimg w-full md:grow md:basis-1/2"
              ref={ref}
              style={{
                ...inView,
              }}
            >
              <SimpleParallax scale={1.4} overflow={0}>
                <img
                  className="object-cover w-full h-80 md:h-96 lg:h-80"
                  loading="lazy"
                  src={aboutimg}
                  alt="About section image"
                />
              </SimpleParallax>
            </animated.div>
            <animated.div
              className="intro-content px-2 text-center md:grow md:basis-1/2 md:pt-4 md:text-left"
              ref={ref2}
              style={{
                ...inView2,
              }}
            >
              <p>
                <b>Lorem Ipsum</b> is simply dummy text of the printing and
                typesetting industry. Lorem Ipsum has been the industry's
                standard dummy text ever since the 1500s, when an unknown
                printer took a galley of type and scrambled it to make a type
                specimen book. It has survived not only five centuries, but also
                the leap into electronic typesetting, remaining essentially
                unchanged. It was popularised in the 1960s with the release of
                Letraset sheets containing Lorem Ipsum passages, and more
                recently with desktop publishing software like Aldus PageMaker
                including versions of Lorem Ipsum.
              </p>
              <ViewMore />
            </animated.div>
          </div>
          <div className="about-content overflow-hidden">
            <div className="about-icons mb-4 relative float-left">
              <div className="icon-stage flex flex-wrap gap-2">
                {icons.map((item, i) => (
                  <AnimatedIcon
                    key={i}
                    title={item.title}
                    icon={item.icon}
                    content={item.content}
                    /* entryIndexRef={entryIndexRef} */
                  />
                ))}
              </div>
            </div>
            {isPage && (
              <>
                <h2 className="text-xl font-semibold uppercase">
                  <span className="text-[#007575]">Where does it</span> come
                  from?
                </h2>
                <p>
                  Contrary to popular belief, Lorem Ipsum is not simply random
                  text. It has roots in a piece of classical Latin literature
                  from 45 BC, making it over 2000 years old. Richard McClintock,
                  a Latin professor at Hampden-Sydney College in Virginia,
                  looked up one of the more obscure Latin words, consectetur,
                  from a Lorem Ipsum passage, and going through the cites of the
                  word in classical literature, discovered the undoubtable
                  source. Lorem Ipsum comes from sections 1.10.32 and 1.10.33 of
                  "de Finibus Bonorum et Malorum" (The Extremes of Good and
                  Evil) by Cicero, written in 45 BC. This book is a treatise on
                  the theory of ethics, very popular during the Renaissance. The
                  first line of Lorem Ipsum, "Lorem ipsum dolor sit amet..",
                  comes from a line in section 1.10.32.
                </p>
                <p>
                  The standard chunk of Lorem Ipsum used since the 1500s is
                  reproduced below for those interested. Sections 1.10.32 and
                  1.10.33 from "de Finibus Bonorum et Malorum" by Cicero are
                  also reproduced in their exact original form, accompanied by
                  English versions from the 1914 translation by H. Rackham.
                </p>
              </>
            )}
          </div>
          <div className={!isPage ? "flex justify-center gap-4" : "block"}>
            <div className={"button" + (!isPage ? " py-4 !mr-0" : "")}>
              <button
                className="block px-4 py-2 mb-2 bg-gradient-to-r from-blue-600 to-blue-500 text-center text-[#e0eefe] shadow-lg pointer rounded-md text-sm"
                onClick={openModal}
              >
                Open Modal
              </button>
              <Modal show={isModalOpen} onClose={closeModal} />
            </div>
            <div className={"button" + (!isPage ? " py-4 !mr-0" : "")}>
              <button
                className="block px-4 py-2 mb-2 bg-gradient-to-r from-blue-600 to-blue-500 text-center text-[#e0eefe] shadow-lg pointer rounded-md text-sm"
                onClick={openModalCta}
              >
                Open CTA
              </button>
              <ModalCta show={isModalCtaOpen} onClose={closeModalCta} />
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

const About = () => {
  return (
    <>
      <title>About Us</title>
      <meta name="description" content="About Us" />
      <meta property="og:title" content="About Us | My New React App" />
      <meta property="og:image" content={aboutimg} />
      <main id="main">
        <div className="about-page-section">
          <AboutContent />
        </div>
      </main>
    </>
  );
};

export default About;
