import { useState, version } from "react";
import { useForm, Controller } from "react-hook-form";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCalendar,
  faChevronDown,
  faEye,
  faEyeSlash,
} from "@fortawesome/free-solid-svg-icons";
import DatePicker from "react-datepicker";
import { useNavigate } from "react-router-dom";
import logo from "../../logo.webp";

const Signup = () => {
  const {
    register,
    control,
    watch,
    handleSubmit,
    reset,
    setError,
    formState: { errors },
  } = useForm();
  const password = watch("password");
  const [loading, setLoading] = useState(false);
  const [seePassword, setSeePassword] = useState(false);
  const [seeRepeatPassword, setSeeRepeatPassword] = useState(false);
  const [step, setStep] = useState("form"); // "form" | "otp"
  const [pendingEmail, setPendingEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [otpError, setOtpError] = useState("");
  const navigate = useNavigate();
  const changePath = () => {
    navigate("/user/login");
  };

  const onSignup = async (data) => {
    setLoading(true);
    try {
            const res = await fetch("https://user-server-nzts.onrender.com/user/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
        credentials: "include",
      });
      const result = await res.json();
      if (result.status === "Failed" && result.field && result.message) {
        setError(result.field, {
          type: "server",
          message: result.message,
        });
      } else if (result.status === "Success") {
        reset();
        navigate(`/user/verify?token=${result.token}`)
      }
    } catch (err) {
      console.log(err);
    } finally {
      setLoading(false);
    }
  };

  const onVerifyOtp = async (e) => {
    e.preventDefault();
    setLoading(true);
    setOtpError("");
    try {
      const res = await fetch("https://user-server-nzts.onrender.com/user/signup/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: pendingEmail, otp }),
        credentials: "include",
      });
      const result = await res.json();
      if (result.status === "Success") {
        reset();
        navigate("/user/login");
      } else {
        setOtpError(result.message);
      }
    } catch (err) {
      console.log(err);
    } finally {
      setLoading(false);
    }
  };

  const onResendOtp = async () => {
    try {
      const res = await fetch("https://user-server-nzts.onrender.com/user/signup/resend-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: pendingEmail }),
        credentials: "include",
      });
      const result = await res.json();
      setOtpError(result.message);
    } catch (err) {
      console.log(err);
    }
  };

  if (step === "otp") {
    return (
      <main id="main">
        <div className="signup-page-section">
          <h1 className="text-center text-3xl font-bold">
            <span>Verify</span> your email
          </h1>
          <div className="container">
            <div className="max-w-[480px] m-auto">
              <p className="mb-4">
                Enter the 6-digit code sent to {pendingEmail}
              </p>
              <form onSubmit={onVerifyOtp}>
                <input
                  className="w-full h-12 rounded-md border-2 p-2 tracking-widest text-lg"
                  maxLength={6}
                  inputMode="numeric"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
                  placeholder="Example: 123456"
                />
                {otpError && <small style={{ color: "red" }}>{otpError}</small>}
                <div className="mb-4 text-center md:px-2 mt-4">
                  <div className="button">
                    <button
                      type="submit"
                      disabled={loading || otp.length !== 6}
                      className="block px-4 py-2 mb-2 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] disabled:cursor-not-allowed rounded-md text-sm"
                    >
                      {loading ? "Verifying..." : "Verify"}
                    </button>
                  </div>
                </div>
                <div className="mb-4 text-center md:px-2 mt-4">
                  <div className="button">
                    <button
                      type="button"
                      onClick={onResendOtp}
                      className="text-sm underline text-[#008b8b]"
                    >
                      Resend OTP
                    </button>
                  </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <>
      <title>Signup</title>
      <meta name="description" content="Signup" />
      <meta property="og:title" content="Signup | My New React App" />
      <meta property="og:image" content={logo} />
      <main id="main">
        <div className="signup-page-section">
          <h1 className="text-center text-3xl font-bold">
            <span>Sign</span>up
          </h1>
          <div className="container">
            <div className="max-w-[480px] m-auto">
              <div className="signupform">
                <div className="mb-4 text-center md:px-2">
                  <div className="button">
                    <button
                      onClick={changePath}
                      className="block font-semibold text-[#008b8b] hue-rotate-[45deg] text-lg underline pointer"
                      disabled={loading}
                    >
                      Already have an account? Login here
                    </button>
                  </div>
                </div>
                {loading ? (
                  <div className="flex justify-center py-16">
                    <span className="relative flex items-center justify-center size-24">
                      <span className="absolute inline-flex h-full w-full animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-[#61dafb]"></span>
                      <span className="relative inline-flex items-center justify-center size-24 animate-pulse rounded-full bg-[#61dafb] text-xs text-slate-500">
                        <span className="absolute inline-flex h-1/2 w-1/2 animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-slate-500"></span>
                        Please wait...
                      </span>
                    </span>
                  </div>
                ) : (
                  <form onSubmit={handleSubmit(onSignup)} autoComplete="off">
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="firstname">First Name</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="firstname"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          type="text"
                          autoComplete="on"
                          placeholder="Enter your first name"
                          {...register("firstname", {
                            required: "First name is required",
                            pattern: {
                              value: /^[A-Za-z]+$/i,
                              message: "Only alphabets are allowed",
                            },
                          })}
                        />
                        {errors.firstname && (
                          <small style={{ color: "red" }}>
                            {errors.firstname.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="lastname">Last Name</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="lastname"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          type="text"
                          autoComplete="on"
                          placeholder="Enter your last name"
                          {...register("lastname", {
                            pattern: {
                              value: /^[A-Za-z]+$/i,
                              message: "Only alphabets are allowed",
                            },
                          })}
                        />
                        {errors.lastname && (
                          <small style={{ color: "red" }}>
                            {errors.lastname.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="email">Email</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="email"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          autoComplete="on"
                          placeholder="Enter a valid email address"
                          type="email"
                          {...register("email", {
                            required: "Email address is required",
                            pattern: {
                              value: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/,
                              message: "Enter a valid email address",
                            },
                          })}
                        />
                        {errors.email && (
                          <small style={{ color: "red" }}>
                            {errors.email.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="password">Password</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="password"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          type={seePassword ? "text" : "password"}
                          autoComplete="on"
                          placeholder="Enter your password"
                          minLength={8}
                          maxLength={28}
                          {...register("password", {
                            required: "Password is required",
                          })}
                        />
                        <FontAwesomeIcon
                          onClick={() => setSeePassword((prev) => !prev)}
                          icon={seePassword ? faEye : faEyeSlash}
                          color="#272b36"
                          size="xl"
                          className="absolute right-2 top-1/2 transform -translate-y-1/2 cursor-pointer"
                        />
                        {errors.singup_password && (
                          <small style={{ color: "red" }}>
                            {errors.password.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="repeat_password">Repeat password</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="repeat_password"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          type={seeRepeatPassword ? "text" : "password"}
                          autoComplete="on"
                          placeholder="Enter your password"
                          {...register("repeat_password", {
                            required: "Password is required",
                            validate: (value) =>
                              value === password || "Password doesn't match",
                          })}
                        />
                        <FontAwesomeIcon
                          onClick={() => setSeeRepeatPassword((prev) => !prev)}
                          icon={seeRepeatPassword ? faEye : faEyeSlash}
                          color="#272b36"
                          size="xl"
                          className="absolute right-2 top-1/2 transform -translate-y-1/2 cursor-pointer"
                        />
                        {errors.repeat_password && (
                          <small style={{ color: "red" }}>
                            {errors.repeat_password.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="tel">Phone</label>
                      </div>
                      <div className="relative form-field">
                        <input
                          id="tel"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                          autoComplete="on"
                          placeholder="Enter your phone number"
                          type="tel"
                          inputMode="numeric"
                          maxLength={10}
                          {...register("phone", {
                            required: "Phone number is required",
                            pattern: {
                              value: /^[0-9]{10}$/,
                              message: "Phone number must be 10 digits only",
                            },
                          })}
                        />
                        {errors.phone && (
                          <small style={{ color: "red" }}>
                            {errors.phone.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 overflow-hidden md:px-2">
                      <div className="label">
                        <label htmlFor="gender">Gender</label>
                      </div>
                      <div className="relative form-field">
                        <select
                          id="gender"
                          className="w-full h-12 rounded-md border-2 p-2 appearance-none cursor-pointer"
                          {...register("gender", {
                            required: "Gender is required",
                            message: "Please select an option",
                          })}
                          defaultValue=""
                        >
                          <option value="" disabled hidden>
                            Select your gender
                          </option>
                          <option value="male">Male</option>
                          <option value="female">Female</option>
                        </select>
                        <FontAwesomeIcon
                          icon={faChevronDown}
                          color="#272b36"
                          size="xl"
                          className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 pointer-events-none"
                        />
                      </div>
                      {errors.gender && (
                        <small style={{ color: "red" }}>
                          {errors.gender.message}
                        </small>
                      )}
                    </div>
                    <div className="mb-4 md:px-2">
                      <div className="label">
                        <label htmlFor="dob">Date of Birth</label>
                      </div>
                      <div className="relative form-field">
                        <Controller
                          name="dob"
                          control={control}
                          defaultValue={null}
                          rules={{
                            required: "Date of birth is required",
                            message: "Please select date of birth",
                          }}
                          render={({ field }) => (
                            <DatePicker
                              className="w-full h-12 rounded-md border-2 !p-2 appearance-none cursor-pointer"
                              id="dob"
                              wrapperClassName="w-full"
                              showIcon
                              icon={
                                <FontAwesomeIcon
                                  icon={faCalendar}
                                  color="#272b36"
                                  size="xl"
                                  className="right-2 top-1/2 transform -translate-y-1/2 cursor-pointer"
                                />
                              }
                              toggleCalendarOnIconClick
                              placeholderText="Select your date of Birth"
                              selected={field.value}
                              onChange={(date) => field.onChange(date)}
                              dateFormat="yyyy-MM-dd"
                              maxDate={new Date()}
                              showTimeSelect={false}
                              showMonthDropdown
                              showYearDropdown
                              scrollableYearDropdown
                              yearDropdownItemNumber={18}
                              dropdownMode="scroll"
                            />
                          )}
                        />
                        {errors.dob && (
                          <small style={{ color: "red" }}>
                            {errors.dob.message}
                          </small>
                        )}
                      </div>
                    </div>
                    <div className="mb-4 text-center md:px-2">
                      <div className="button">
                        <button
                          className="block px-4 py-2 mb-2 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-md text-sm"
                          type="submit"
                          disabled={loading}
                        >
                          {loading ? "Signing Up" : "Sign Up"}
                        </button>
                      </div>
                    </div>
                  </form>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>
    </>
  );
};
export default Signup;
