import { faBan } from "@fortawesome/free-solid-svg-icons";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { Link } from "react-router-dom";
import logo from "../logo.webp";
import { useEffect } from "react";

function PageNotFound() {
    useEffect(() => {
        document.documentElement.setAttribute('error', '404');

        return () => {
            document.documentElement.removeAttribute("error");
        }
    },[])
    return (
        <>
            <title>404 - Page Not Found</title>
            <meta name="description" content="404 - Page Not Found" />
            <meta property="og:title" content="404 | Page Not Found" />
            <meta property="og:image" content={logo} />
            <main id="main" className="flex items-center justify-center">
                <div className="404-page text-center">
                    <div className="container">
                        <div className='m-4'>
                            <h1 className="text-center text-4xl font-bold"><span>404</span> Page Not Found</h1>
                            <FontAwesomeIcon icon={faBan} size="10x" opacity={0.1} />
                            <p className="m-2">The page you are trying to browse doesn't exist</p>
                            <div className="404-nav">
                                <div className="button">
                                    <button>
                                        <Link to={"/"} className="block px-4 py-2 mb-1 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-md text-sm">Home</Link>
                                    </button>
                                </div>
                                <div className="button">
                                    <button>
                                        <Link to={"/user/login"} className="block px-4 py-2 mb-1 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-md text-sm">Login</Link>
                                    </button>
                                </div>
                                <div className="button">
                                    <button>
                                        <Link to={"/user-signup"} className="block px-4 py-2 mb-1 bg-[#008b8b] text-black uppercase shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-md text-sm">Signup</Link>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        </>
    )
}
export default PageNotFound;