import { useEffect, useState, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAddressCard, faBars, faChevronDown, faHome, faImage, faMoon, faPhone, faSignOut, faSignOutAlt, faStar, faSun, faUser, faUserCircle, faXmark } from '@fortawesome/free-solid-svg-icons';
import { useSpring, animated } from '@react-spring/web';
import { useAuth } from './user/auth/auth';
import { useTheme } from './DarkMode';

const Menu = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [openSubmenu, setOpenSubmenu] = useState(false);
  const menuRef = useRef(null);
  const iconRef = useRef(null);
  const submenuRef = useRef(null);
  const isMobile = window.innerWidth < 1024;
  const { user } = useAuth();
  const auth = useAuth();
  const { dark, enable } = useTheme();

  const onLogout = async () => {
    await fetch('https://user-server-nzts.onrender.com/user/logout', {
      method: "POST",
      credentials: "include"
    });
    auth.logout();
  }

  const menuAnimation = useSpring({
    opacity: isMobile ? (isOpen ? 1 : 0) : '',
    maxWidth: isMobile ? 270 : '',
    maxHeight: isMobile ? (isOpen ? 500 : 0) : '',
    top: isMobile ? 'unset' : '',
    right: isMobile ? '0%' : '',
    left: isMobile ? 'unset' : '',
    transform: isMobile ? (isOpen ? 'scale(1)' : 'scale(0)') : '',
    transformOrigin: isMobile ? 'right top' : '',
    //overflow: isMobile ? (isOpen ? 'auto' : 'hidden') : 'auto',
    config: { tension: 300, friction: 30 },
  });

  const location = useLocation();
  const pathnames = location.pathname;
  const myAccount = location.pathname.startsWith('/my-account');

  const submenuAnimation = useSpring({
    opacity: isMobile ? (myAccount ? 1 : (openSubmenu ? 1 : 0)) : '',
    maxHeight: isMobile ? (myAccount ? 500 : (openSubmenu ? 500 : 0)) : '',
    transform: isMobile ? (myAccount ? 'scaleY(100%)' : (openSubmenu ? 'scaleY(100%)' : 'scaleY(0%)')) : '',
    //overflow: isMobile ? (openSubmenu ? 'auto' : 'hidden') : 'auto',
    borderTopWidth: isMobile ? (myAccount ? '4px' : (openSubmenu ? '4px' : '0')) : '0',
    config: { tension: 300, friction: 30 },
  })

  useEffect(() => {
    const body = document.body;
    const menuElem = document.querySelector('.mobile-menu');

    if (isOpen && isMobile) {
      body.classList.add('menu-active');
      menuElem?.classList.add('menu-active');
    } else {
      body.classList.remove('menu-active');
      menuElem?.classList.remove('menu-active');
      document.querySelectorAll('li.parent').forEach(el => {
        //el.classList.remove('active');
        setOpenSubmenu(false);
      });
    }
  }, [isOpen, isMobile]);

  useEffect(() => {
    const handleClickOut = (e) => {
      if (
        isOpen &&
        menuRef.current &&
        !menuRef.current.contains(e.target) &&
        iconRef.current &&
        !iconRef.current.contains(e.target)
      ) {
        setIsOpen(false);
        setOpenSubmenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOut);
    return () => document.addEventListener('mousedown', handleClickOut);
  }, [isOpen]);

  const handleLinkClick = () => {
    setIsOpen(false);
    setOpenSubmenu(false);
  }

  useEffect(() => {
    const subMenu = document.querySelector('nav > .mainmenu > li.parent');

    if (openSubmenu && isMobile) {
      subMenu?.classList.add('active');
    } else if (isMobile && myAccount) {
      subMenu?.classList.add('active');
    }
    else {
      subMenu?.classList.remove('active');
    }
  }, [pathnames, openSubmenu, isMobile]);

  const handleTheme = async () => {
    enable();

    try {
      const res = await fetch('https://user-server-nzts.onrender.com/user/theme', {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: user._id, updates: { darkMode: !dark } })
      });
      const result = await res.json();
      return result;
    } catch (err) {
      console.error(err);
    }
  }

  return (
    <>
      {isMobile ? <div className='mobile-menu'><Link to='' ref={iconRef} onClick={(e) => { e.preventDefault(); setIsOpen(prev => !prev) }} className='text-[#272b36] text-5xl' aria-label='Menu'><FontAwesomeIcon icon={isOpen ? faXmark : faBars} /></Link></div> : null}
      <nav>
        <animated.ul ref={menuRef} style={menuAnimation} className={'mainmenu text-left px-2 py-4 w-full items-center fixed left-0 top-[90px] text-sm bg-[#f0f3f5] overflow-hidden rounded-lg lg:text-base lg:flex lg:flex-wrap lg:justify-end lg:gap-y-3 lg:[position:unset] lg:bg-transparent' + (isMobile ? ' shadow-lg' : '')}>
          <li className='group mx-2 select-none relative overflow-hidden rounded-lg lg:float-left'>
            <Link onClick={handleLinkClick} to="/" className={'block px-2 py-2 font-bold text-[#272b36] duration-300 before:opacity-0 before:bg-gradient-to-r  before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe]' + (pathnames === '/' ? ' pointer-events-none text-[#e0eefe] before:!opacity-[1]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faHome} size='lg' className='mr-2' /> : ''}Home</Link>
          </li>
          <li className='group mx-2 select-none relative overflow-hidden rounded-lg lg:float-left'>
            <Link onClick={handleLinkClick} to="/about" className={'block p-2 font-bold text-[#272b36] duration-300 before:opacity-0 before:bg-gradient-to-r  before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe]' + (pathnames === '/about' ? ' pointer-events-none text-[#e0eefe] before:!opacity-[1]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faAddressCard} size='lg' className='mr-2' /> : ''}About</Link>
          </li>
          <li className='group mx-2 select-none relative overflow-hidden rounded-lg lg:float-left'>
            <Link onClick={handleLinkClick} to="/gallery" className={'block p-2 font-bold text-[#272b36] duration-300 before:opacity-0 before:bg-gradient-to-r  before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe]' + (pathnames === '/gallery' ? ' pointer-events-none text-[#e0eefe] before:!opacity-[1]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faImage} size='lg' className='mr-2' /> : ''}Gallery</Link>
          </li>
          <li className='group mx-2 select-none relative overflow-hidden rounded-lg lg:float-left'>
            <Link onClick={handleLinkClick} to="/testimonials" className={'block p-2 font-bold text-[#272b36] duration-300 before:opacity-0 before:bg-gradient-to-r  before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe]' + (pathnames === '/testimonials' ? ' pointer-events-none text-[#e0eefe] before:!opacity-[1]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faStar} size='lg' className='mr-2' /> : ''}Testimonials</Link>
          </li>
          <li className='group mx-2 select-none relative overflow-hidden rounded-lg lg:float-left'>
            <Link onClick={handleLinkClick} to="/contact-us" className={'block p-2 font-bold text-[#272b36] duration-300 before:opacity-0 before:bg-gradient-to-r  before:from-blue-600 before:to-blue-500 hover:before:opacity-[1] hover:text-[#e0eefe]' + (pathnames === '/contact-us' ? ' pointer-events-none text-[#e0eefe] before:!opacity-[1]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faPhone} size='lg' className='mr-2' /> : ''}Contact Us</Link>
          </li>
          {isMobile ?
            <li onClick={() => { setOpenSubmenu(prev => !prev); }} className={'parent group relative overflow-hidden mx-2 px-2 rounded-lg leading-9 font-bold text-[#272b36] hover:bg-gradient-to-r hover:from-blue-600 hover:to-blue-500 hover:text-[#e0eefe] lg:float-left cursor-pointer' + (openSubmenu || myAccount ? ' bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe]' : '')}>
              {isMobile ? <FontAwesomeIcon icon={faUserCircle} size='lg' className='mr-2' /> : ''}
              My Account
              <FontAwesomeIcon icon={faChevronDown} className={'px-1' + (myAccount ? ' text-[#e0eefe]' : '')} />
              <animated.ul ref={submenuRef} style={submenuAnimation} className='submenu max-w-[250px] -mx-2 my-auto text-sm bg-[#272b36] overflow-hidden origin-top lg:py-4 lg:opacity-0 lg:scale-y-0 lg:group-hover:opacity-[1] lg:group-hover:scale-y-[1] lg:duration-300 lg:absolute lg:w-full lg:left-[unset] lg:right-1'>
                <li className={'border-b-2 text-[#e0eefe] lg:bg-slate-500 lg:hover:text-[#272b36]' + (myAccount ? ' current text-blue-600 pointer-events-none opacity-50' : '')}>
                  <Link onClick={handleLinkClick} to={'/my-account'} className='block p-2 font-bold'>
                    <FontAwesomeIcon icon={faUser} size='lg' className='mr-2' />Dashboard</Link>
                </li>
                <li className='border-b-2 text-[#e0eefe] lg:bg-slate-500 lg:hover:text-[#272b36]'>
                  <Link onClick={onLogout} to={'/#logout'} className='block p-2 font-bold'>
                    <FontAwesomeIcon icon={faSignOutAlt} size='lg' className='mr-2' />Logout</Link>
                </li>
                <li className='font-bold p-2 text-[#e0eefe] cursor-context-menu lg:bg-slate-500 lg:hover:text-[#272b36]'>
                  <FontAwesomeIcon icon={dark ? faMoon : faSun} size='lg' className='mr-2' />
                  Theme
                  <label className="switch inline-block justify-items-center ml-2 cursor-pointer" htmlFor="theme">
                    <input onClick={handleTheme} type="checkbox" id="theme" name="theme" value={dark ? "on" : "off"} className='h-0 w-0 opacity-0' />
                    <span className='inline-block relative w-12 h-6 duration-300 align-middle rounded-2xl before:duration-300'></span>
                  </label>
                </li>
              </animated.ul>
            </li> : null
          }
        </animated.ul>
      </nav>
    </>
  );
}

export default Menu;