import { createPortal } from "react-dom";
import { useSpring, animated } from "@react-spring/web";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTimes } from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";
import { useAuth } from "../user/auth/auth";
import { useEffect, useState } from "react";

export const Modal = ({ show, onClose }) => {
  const auth = useAuth();
  const [isModalOpen, setModalOpen] = useState(false);
  const SESSION_KEY = "welcomeModalClosed";
  useEffect(() => {
    if (!sessionStorage.getItem(SESSION_KEY) && auth.user) {
      setModalOpen(true);
      document.documentElement.setAttribute("modal", "open");
    }
  }, [auth.user]);
  const springProps = useSpring({
    opacity: show ? 1 : 0,
    transform: show ? "translateY(0)" : "translateY(-50px)",
    config: { tension: 300, friction: 60 },
  });

  if (!show) return null;

  return createPortal(
    <>
      {isModalOpen ? (
        <div
          id="welcomeModal"
          className="modal-overlay hidden fixed bg-[#00000080] [html[modal='open']_&]:flex justify-center items-center z-50 top-0 left-0 w-full h-full"
        >
          <animated.div
            className="modal relative mx-4 bg-gradient-to-bl from-sky-300 to-sky-200 p-4 rounded-md max-w-3xl w-full shadow-lg lg:mx-0"
            style={springProps}
          >
            <div className="modal-header overflow-hidden">
              <button
                className="close-button px-4 py-2 absolute top-2 right-2 text-sm text-sm bg-gradient-to-bl from-blue-600 to-blue-500 text-[#f0f3f5] capitalize shadow-lg rounded-md sm:text-lg"
                onClick={onClose}
              >
                <FontAwesomeIcon icon={faTimes} />
              </button>
              <h2>Modal Title</h2>
            </div>
            <div className="modal-content">
              <div className="">
                <p>
                  <b>Lorem Ipsum</b> is simply dummy text of the printing and
                  typesetting industry. Lorem Ipsum has been the industry's
                  standard dummy text ever since the 1500s, when an unknown
                  printer took a galley of type and scrambled it to make a type
                  specimen book. It has survived not only five centuries, but
                  also the leap into electronic typesetting, remaining
                  essentially unchanged. It was popularised in the 1960s with
                  the release of Letraset sheets containing Lorem Ipsum
                  passages, and more recently with desktop publishing software
                  like Aldus PageMaker including versions of Lorem Ipsum.
                </p>
              </div>
            </div>
            <div className="modal-footer">
              <button onClick={onClose}>
                <Link
                  className="block px-4 py-2 mb-1 bg-gradient-to-bl from-blue-600 to-blue-500 text-white capitalize shadow-lg pointer rounded-md text-sm"
                  to="/about"
                >
                  View More
                </Link>
              </button>
            </div>
          </animated.div>
        </div>
      ) : null}
    </>,
    document.body,
  );
};
