import logo from '../logo.webp';
import Menu from './Menu';
import Breadcrumbs from './Breadcrumbs';
import { useSpring, animated } from '@react-spring/web';
import { useAuth } from './user/auth/auth';
import { useTheme } from './DarkMode'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faChevronDown, faCircleUser, faMoon, faSignOut, faSignOutAlt, faSun, faUser, faUserAlt } from '@fortawesome/free-solid-svg-icons';
import { Link } from 'react-router-dom';
import { useState } from 'react';

const Header = () => {
  const isMobile = window.innerWidth < 1024;
  const auth = useAuth();
  const { user } = useAuth();
  const { dark, enable } = useTheme();
  const [isHover, setHover] = useState(false);

  const rotateInf = useSpring({
    from: { rotate: 0 },
    to: { rotate: 360 },
    loop: true,
    config: { duration: 20000 },
  });

  const onLogout = async () => {
    await fetch('https://user-server-nzts.onrender.com/user/logout', {
      method: "POST",
      credentials: "include"
    });
    auth.logout();
  }

  const handleTheme = async () => {
    enable();

    try {
      const res = await fetch('https://user-server-nzts.onrender.com/user/theme', {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: user._id, updates: { darkMode: !dark } })
      });
      const result = await res.json();
      return result;
    } catch (err) {
      console.error(err);
    }
  }

  const styles = useSpring({
    backgroundImage: isHover ? 'linear-gradient(-90deg, rgb(2, 132, 199), rgb(14, 165, 233))' : 'linear-gradient(90deg, rgb(37, 99, 235), rgb(59, 130, 246))',
    config: {
      tension: 300,
      friction: 30
    }
  });

  return (
    <>
      {!auth.user ? null :
        <div className="App z-50 relative">
          <header className="App-header flex justify-between items-center bg-[#e0eefe] fixed w-full z-40 transition-[all_0.3s_ease-in-out] shadow-lg lg:max-w-[95vw] lg:px-6 lg:left-1/2 lg:top-4 lg:translate-x-[-50%] lg:rounded-full">
            <div id='logo'>
              <Link to={'/'} title='Home' className='flex items-center'>
                <animated.img /* style={{ ...rotateInf }} */ loading="lazy" height="96" width="96" src={logo} className="App-logo p-2 duration-300 max-lg:[.page-home.scrolled_&]:w-16" alt="logo"></animated.img>
                <div className='text-left text-md lg:text-2xl'>
                  <span className='font-bold text-[#008b8b] hue-rotate-[45deg]'>N</span>ew<span className='font-bold text-[#008b8b] hue-rotate-[45deg]'> R</span>eact<br/><span className='font-bold text-[#008b8b] hue-rotate-[45deg]'>S</span>ite
                </div>
              </Link>
            </div>
            <div className='menu relative max-lg:grow-0 max-lg:justify-items-end'>
              <Menu />
            </div>
            {isMobile ? null :
              <div className='account cursor-pointer'>
                <ul>
                  <animated.li
                    className='group relative text-[#e0eefe] px-4 py-2 rounded-xl duration-300'
                    onMouseEnter={() => setHover(true)}
                    onMouseLeave={() => setHover(false)}
                    onFocus={() => setHover(true)}
                    onBlur={() => setHover(false)}
                    style={{ ...styles }}
                    tabIndex={0}
                  >
                    <FontAwesomeIcon icon={faCircleUser} size='2xl' className='mr-2' />
                    <FontAwesomeIcon icon={faChevronDown} />
                    <ul className='fixed opacity-0 collapse text-left max-w-64 w-full bg-[#f0f3f5] p-4 mt-2 right-6 rounded-xl shadow-lg duration-300 group-hover:opacity-[1] group-hover:visible'>
                      <li className='relative overflow-hidden font-bold text-[#272b36] before:opacity-0 hover:before:opacity-[1] hover:before:bg-gradient-to-r hover:before:from-blue-600 hover:before:to-blue-500 hover:text-[#e0eefe] [.page-my-account_&]:before:opacity-[1] [.page-my-account_&]:before:bg-gradient-to-r [.page-my-account_&]:before:from-blue-600 [.page-my-account_&]:before:to-blue-500 [.page-my-account_&]:text-[#e0eefe] rounded-lg'>
                        <Link to={'/my-account'} className='block px-2 py-4 border-b-2 border-slate-300 [.page-my-account_&]:pointer-events-none'>
                          <FontAwesomeIcon icon={faUser} size='xl' className='mr-2' />Dashboard</Link></li>
                      <li className='relative overflow-hidden font-bold text-[#272b36] before:opacity-0 hover:before:opacity-[1] hover:before:bg-gradient-to-r hover:before:from-blue-600 hover:before:to-blue-500 hover:text-[#e0eefe] rounded-lg'>
                        <Link onClick={onLogout} to={'/#logout'} className='block px-2 py-4'>
                          <FontAwesomeIcon icon={faSignOutAlt} size='xl' className='mr-2' />Logout</Link></li>
                      <li className='relative overflow-hidden font-bold px-2 py-4 text-[#272b36] before:opacity-0 hover:before:opacity-[1] hover:before:bg-gradient-to-r hover:before:from-blue-600 hover:before:to-blue-500 hover:text-[#e0eefe] rounded-lg'>
                        <FontAwesomeIcon icon={dark ? faMoon : faSun} size='xl' className='mr-2' />
                        Theme
                        <label className="switch inline-block justify-items-center ml-2 cursor-pointer" htmlFor="theme">
                          <input onClick={handleTheme} type="checkbox" id="theme" name="theme" value={dark ? "on" : "off"} className='h-0 w-0 opacity-0' />
                          <span className='inline-block relative w-12 h-6 duration-300 align-middle rounded-2xl before:duration-300'></span>
                        </label>
                      </li>
                    </ul>
                  </animated.li>
                </ul>
              </div>
            }
          </header>
          <div className='breadcrumbs bg-[#272b36] fixed w-full top-24 duration-300'>
            <Breadcrumbs />
          </div>
        </div>
      }
    </>
  );
}

export default Header;