import { useSpring, animated } from '@react-spring/web';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTimes, faCalendar, faChevronDown, faPen } from '@fortawesome/free-solid-svg-icons';
import { useForm, Controller } from 'react-hook-form';
import DatePicker from "react-datepicker";
import { useEffect, useState } from 'react';
import { useAuth } from './auth/auth';

export const AccountChanges = ({ show, onClose }) => {
    const { user } = useAuth();
    const { register, control, handleSubmit, reset, setError, formState: { errors } } = useForm({
        defaultValues: {
            firstname: user.firstname,
            lastname: user.lastname,
            email: user.email,
            phone: user.phone,
            gender: user.gender,
            dob: user.dob,
        }
    });
    const [isDisabled, setIsDisabled] = useState({});
    useEffect(() => {
        if (show) {
            setIsDisabled({
                firstname: false,
                lastname: false,
                email: false,
                phone: false,
                gender: false,
                dob: false
            })
        }
    }, [show]);
    const toggleField = (field) => {
        setIsDisabled((prev) => ({
            ...prev,
            [field]: !prev[field],
        }));
    }
    const [loading, setLoading] = useState(false);
    const springProps = useSpring({
        opacity: show ? 1 : 0,
        transform: show ? 'translateY(0)' : 'translateY(-50px)',
        config: { tension: 250, friction: 20 },
    });
    if (!show) return null;

    const onAccountChange = async (updates) => {
        const filtered = Object.fromEntries(
            Object.entries(updates).filter((_, v) => v !== "")
        );
        setLoading(true);
        try {
            const res = await fetch('https://user-server-nzts.onrender.com/user/updates', {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ userId: user._id, updates: filtered }),
                credentials: "include"
            });
            const result = await res.json();
            if (result.status === "Success") {
                reset();
                onClose?.();
            }
        } catch (err) {
            console.log(err);
        } finally {
            setLoading(false);
        }
    }

    return (
        <div className="modal-overlay fixed bg-[#00000080] flex justify-center items-center z-50 top-0 left-0 w-full h-full">
            <animated.div className="modal-content relative bg-gradient-to-bl from-sky-200 to-sky-50 p-4 rounded-md max-w-lg w-full" style={springProps}>
                <button className="close-button px-4 py-2 absolute top-2 right-2 text-sm text-sm bg-gradient-to-r from-blue-600 to-blue-500 text-[#f0f3f5] uppercase rounded-md sm:text-lg" onClick={onClose}><FontAwesomeIcon icon={faTimes} /></button>
                <h2>Account changes request form</h2>
                <p>(Fill in the information you would like to change)</p>
                {loading ? (
                    <div className="flex justify-center py-16">
                        <span className="relative flex items-center justify-center size-24">
                            <span className="absolute inline-flex h-full w-full animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-[#61dafb]"></span>
                            <span className="relative inline-flex items-center justify-center size-24 animate-pulse rounded-full bg-[#61dafb] text-xs text-slate-500">
                                <span className="absolute inline-flex h-1/2 w-1/2 animate-[ping_2s_cubic-bezier(0,0.5,1,2)_infinite] rounded-full bg-slate-500"></span>
                                Please wait...</span>
                        </span>
                    </div>
                ) : (
                    <form onSubmit={handleSubmit(onAccountChange)} autoComplete="off">
                        <div className="mb-4 overflow-hidden md:px-2">
                            <div className="label"><label htmlFor="firstname">First Name</label></div>
                            <div className="relative form-field">
                                <input
                                    id="firstname"
                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                    type="text"
                                    disabled={!isDisabled.firstname}
                                    autoComplete="on"
                                    placeholder="Enter your first name"
                                    {...register("firstname", {
                                        //required: "First name is required",
                                        pattern: {
                                            value: /^[A-Za-z]+$/i,
                                            message: "Only alphabets are allowed",
                                        }
                                    })}
                                />
                                {!isDisabled.firstname ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("firstname")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {errors.firstname && <small style={{ color: "red" }}>{errors.firstname.message}</small>}
                            </div>
                        </div>
                        <div className="mb-4 overflow-hidden md:px-2">
                            <div className="label"><label htmlFor="lastname">Last Name</label></div>
                            <div className="relative form-field">
                                <input
                                    id="lastname"
                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                    type="text"
                                    disabled={!isDisabled.lastname}
                                    autoComplete="on"
                                    placeholder="Enter your last name"
                                    {...register("lastname",
                                        {
                                            pattern: {
                                                value: /^[A-Za-z]+$/i,
                                                message: "Only alphabets are allowed",
                                            }
                                        })}
                                />
                                {!isDisabled.lastname ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("lastname")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {errors.lastname && <small style={{ color: "red" }}>{errors.lastname.message}</small>}
                            </div>
                        </div>
                        <div className="mb-4 overflow-hidden md:px-2">
                            <div className="label"><label htmlFor="email">Email</label></div>
                            <div className="relative form-field">
                                <input
                                    id="email"
                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                    autoComplete="on"
                                    placeholder="Enter a valid email address"
                                    type="email"
                                    disabled={!isDisabled.email}
                                    {...register("email",
                                        {
                                            //required: "Email address is required",
                                            pattern: {
                                                value: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/,
                                                message: "Enter a valid email address",
                                            }
                                        })}
                                />
                                {!isDisabled.email ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("email")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {errors.email && <small style={{ color: "red" }}>{errors.email.message}</small>}
                            </div>
                        </div>
                        <div className="mb-4 overflow-hidden md:px-2">
                            <div className="label"><label htmlFor="tel">Phone</label></div>
                            <div className="relative form-field">
                                <input
                                    id="tel"
                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none"
                                    autoComplete="on"
                                    placeholder="Enter your phone number"
                                    type="tel"
                                    disabled={!isDisabled.phone}
                                    inputMode="numeric"
                                    maxLength={10}
                                    {...register("phone",
                                        {
                                            //required: "Phone number is required",
                                            pattern: {
                                                value: /^[0-9]{10}$/,
                                                message: "Phone number must be 10 digits only"
                                            }
                                        })}
                                />
                                {!isDisabled.phone ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("phone")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {errors.phone && <small style={{ color: "red" }}>{errors.phone.message}</small>}
                            </div>
                        </div>
                        <div className="mb-4 overflow-hidden md:px-2">
                            <div className="label"><label htmlFor="gender">Gender</label></div>
                            <div className="relative form-field">
                                <select
                                    id="gender"
                                    className="w-full h-12 rounded-md border-2 p-2 appearance-none cursor-pointer"
                                    disabled={!isDisabled.gender}
                                    {...register("gender",
                                        {
                                            //required: "Gender is required",
                                            message: "Please select an option"
                                        })}
                                    defaultValue="">
                                    {!isDisabled.gender ? <option value="" disabled hidden>{user.gender}</option> : <option value="" disabled hidden>Select your gender</option>}
                                    <option value="male">Male</option>
                                    <option value="female">Female</option>
                                </select>
                                {!isDisabled.gender ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("gender")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {isDisabled.gender ? <FontAwesomeIcon icon={faChevronDown} color="#272b36" size="xl" className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 pointer-events-none" /> : null}
                            </div>
                            {errors.gender && <small style={{ color: "red" }}>{errors.gender.message}</small>}
                        </div>
                        <div className="mb-4 md:px-2">
                            <div className="label"><label htmlFor="dob">Date of Birth</label></div>
                            <div className="relative form-field">
                                <Controller
                                    name="dob"
                                    control={control}
                                    defaultValue={null}
                                    //rules={{ required: "Date of birth is required", message: "Please select date of birth" }}
                                    render={({ field }) => (
                                        <DatePicker
                                            className="w-full h-12 rounded-md border-2 !p-2 appearance-none cursor-pointer"
                                            id="dob"
                                            disabled={!isDisabled.dob}
                                            wrapperClassName="w-full"
                                            showIcon
                                            icon={!isDisabled.dob ? null : <FontAwesomeIcon icon={faCalendar} color="#272b36" size="xl" className="right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" />}
                                            toggleCalendarOnIconClick
                                            placeholderText="Select your date of Birth"
                                            selected={field.value}
                                            onChange={(date) => field.onChange(date)}
                                            dateFormat="yyyy-MM-dd"
                                            maxDate={new Date()}
                                            showTimeSelect={false}
                                            showMonthDropdown
                                            showYearDropdown
                                            scrollableYearDropdown
                                            yearDropdownItemNumber={18}
                                            dropdownMode="scroll"
                                        />
                                    )}
                                />
                                {!isDisabled.dob ? <FontAwesomeIcon icon={faPen} color="#272b36" onClick={() => toggleField("dob")} className="absolute p-2 right-2 top-1/2 transform -translate-y-1/2 cursor-pointer" /> : null}
                                {errors.dob && <small style={{ color: "red" }}>{errors.dob.message}</small>}
                            </div>
                        </div>
                        <div className="mb-4 text-center md:px-2">
                            {!isDisabled.firstname && !isDisabled.lastname && !isDisabled.email && !isDisabled.phone && !isDisabled.gender && !isDisabled.dob ? null : <div className="button"><button className="block px-4 py-2 mb-2 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] capitalize shadow-lg pointer rounded-md text-sm" type="submit" disabled={loading}>{loading ? 'Submitting changes' : 'Submit changes'}</button></div>}
                        </div>
                    </form>
                )}
            </animated.div>
        </div>
    )
}