const OptionalSlider = ({ children, className = "", sliderSettings }) => {
  const location = useLocation();
  const isPage = location.pathname === "/testimonials";
  const breakpointColumnsObj = {
    default: 3,
    1024: 2,
    768: 1,
  };

  if (isPage) {
    return (
      <>
        <title>Testimonials</title>
        <meta name="description" content="Testimonials" />
        <meta property="og:title" content="Testimonials | My New React App" />
        <meta property="og:image" content={logo} />
        <Masonry
          className={className}
          breakpointCols={breakpointColumnsObj}
          columnClassName="testimonials-masonry-grid_column"
        >
          {children}
        </Masonry>
      </>
    );
  }

  return (
    <Slider className={className} {...sliderSettings}>
      {children}
    </Slider>
  );
};

export const RevText = ({ text, maxChars = 350, isExpanded, readMore }) => {
  const shortText = text.length > maxChars;
  const fullText = shortText ? text.slice(0, maxChars) : text;
  const visibleText = shortText ? text.slice(maxChars) : "";

  const readMoreAnimate = useSpring({
    opacity: isExpanded ? "1" : "0",
    config: { friction: 60, tension: 300 },
  });

  return (
    <p className="text-xs text-[#f0f3f5] md:text-sm">
      {fullText}
      {shortText && !isExpanded && "..."}
      {shortText && (
        <animated.span style={{ ...readMoreAnimate }}>
          {isExpanded && visibleText}
        </animated.span>
      )}
      {shortText && (
        <button
          onClick={readMore}
          className={
            "inline text-slate-900 font-bold italic" +
            (isExpanded ? " ml-1" : "")
          }
        >
          {isExpanded ? "Read less" : "Read more"}
        </button>
      )}
    </p>
  );
};

const RevSection = () => {
  const location = useLocation();
  const isPage = location.pathname === "/testimonials";
  const [isExpandedId, setIsExpandedId] = useState(false);
  var readMore = () => setIsExpandedId();
  const settings = {
    centerMode: true,
    className: "testimonialsSlider center my-10",
    centerPadding: "60px",
    touchThreshold: 8,
    dots: true,
    customPaging: (i) => (
      <FontAwesomeIcon
        icon={faCircleDot}
        color="lightgrey"
        size="xs"
        className="[.slick-active_&]:text-lg duration-300"
      />
    ),
    slidesToShow: 3,
    slidesToScroll: 1,
    arrows: true,
    autoplay: true,
    pauseOnHover: true,
    focusOnSelect: true,
    pauseOnFocus: true,
    afterChange: () => readMore(),
    lazyLoad: "ondemand",
    autoplaySpeed: 6000,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 1,
        },
      },
      {
        breakpoint: 640,
        settings: {
          slidesToShow: 1,
          dots: false,
        },
      },
      {
        breakpoint: 480,
        settings: {
          centerPadding: "30px",
          slidesToShow: 1,
          dots: false,
        },
      },
    ],
  };
  const [ref, inView] = useInView(
    () => ({
      from: {
        opacity: 0,
        x: 100,
      },
      to: {
        opacity: 1,
        x: 0,
      },
      config: {
        friction: 60,
        tension: 300,
      },
    }),
    {
      once: true,
      rootMargin: "-50% 0px",
    },
  );

  return (
    <animated.div ref={ref} style={{ overflow: "hidden", ...inView }}>
      <OptionalSlider
        className="testimonials flex gap-2 overflow-hidden"
        sliderSettings={isPage ? "" : { ...settings }}
      >
        {revcontent.map(({ id, revname, rating, text }) => (
          <div key={id} className="mb-2">
            <div
              className={
                "revcontent text-white p-6 bg-gradient-to-br from-blue-600 to-blue-500 shadow-lg duration-500" +
                (isPage ? "" : "")
              }
            >
              <div className="revname">
                <h3 className="text-xl text-[#f0f3f5] font-bold">{revname}</h3>
              </div>
              <div className="revrating mb-2">
                {[...Array(rating)].map((_, i) => (
                  <span key={i} className="revstar">
                    <FontAwesomeIcon icon={faStar} color="yellow" />
                  </span>
                ))}
              </div>
              <div className="revtext">
                <RevText
                  key={id}
                  id={id}
                  text={text}
                  maxChars={350}
                  isExpanded={isExpandedId === id}
                  readMore={() =>
                    setIsExpandedId((prev) => (prev === id ? null : id))
                  }
                />
              </div>
              <div className="revlogo">
                <img src={logo} className="max-w-20" alt="Review logo" />
              </div>
            </div>
          </div>
        ))}
      </OptionalSlider>
    </animated.div>
  );
};

export const TestimonialsSlider = () => {
  const location = useLocation();
  const isPage = location.pathname === "/testimonials";

  return (
    <>
      <RevSection />
      {!isPage && (
        <div className="container">
          <button className="block mx-auto">
            <Link
              className="block px-4 py-2 mb-1 bg-gradient-to-r from-blue-600 to-blue-500 text-[#e0eefe] shadow-lg pointer rounded-md text-sm"
              to="/testimonials"
            >
              Read More Reviews
            </Link>
          </button>
        </div>
      )}
    </>
  );
};

const Testimonials = () => {
  return (
    <main id="main">
      <section className="carousel-wrapper w-full relative">
        <div className="container">
          <div className="m-4">
            <h1 className="text-center text-2xl font-bold capitalize">
              <span>Case</span> Studies
            </h1>
            <TestimonialsSlider />
          </div>
        </div>
      </section>
    </main>
  );
};

export default Testimonials;
